<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,ref,watch} from 'vue';
import type {AiEditorContext,AiEditorHandle,AiEditorSnapshot} from '../types/ai-editor';
const props=defineProps<{context:AiEditorContext;snapshot:AiEditorSnapshot;native?:boolean;formal?:boolean}>();
const root=ref<HTMLElement>(),viewport=ref<HTMLElement>(),world=ref<HTMLElement>(),image=ref<HTMLImageElement>();
const mounting=ref(false),ready=ref(false),mountError=ref('');
let generation=0,alive=true,scope:AiEditorContext|undefined,handle:AiEditorHandle|undefined;
const locked=computed(()=>props.snapshot.saving||props.snapshot.pending||props.snapshot.editingDisabled||!ready.value);
function release(){const owner=scope,current=handle;scope=undefined;handle=undefined;if(owner)owner.release(current)}
function invalidate(){generation++;release();ready.value=false;mounting.value=false;mountError.value=''}
async function mount(){
  const img=image.value,owner=props.context,epoch=generation,id=props.snapshot.imageId,url=props.snapshot.url;
  if(!alive||mounting.value||ready.value||mountError.value||!img?.complete||!img.naturalWidth||!root.value||!viewport.value||!world.value)return;
  if(img.src!==new URL(url,document.baseURI).href)return;
  mounting.value=true;scope=owner;
  try{
    const result=await owner.mount({image:img,viewport:viewport.value,world:world.value,root:root.value});
    if(!alive||epoch!==generation||owner!==props.context||id!==props.snapshot.imageId||url!==props.snapshot.url){if(result)owner.release(result);return}
    handle=result||undefined;ready.value=true;
  }catch(_error){
    if(alive&&epoch===generation){
      release();
      mountError.value=props.native && _error instanceof Error?_error.message:'本地标注组件读取失败，可重试；候选修改由原工作台保留。';
    }
  }finally{if(alive&&epoch===generation)mounting.value=false}
}
async function retry(){invalidate();await nextTick();await mount()}
function imageFailed(){invalidate();mountError.value=props.native?'原图读取失败，请重新载入。':'候选图片读取失败，请通过原工作台重新载入。'}
function changed(event:Event){return (event.target as HTMLSelectElement).value}
watch([()=>props.context,()=>props.snapshot.imageId,()=>props.snapshot.url],async()=>{invalidate();await nextTick();await mount()},{immediate:true,flush:'post'});
onBeforeUnmount(()=>{alive=false;invalidate()});
</script>
<template><section ref="root" class="vue-annotation-editor" :aria-label="formal?'正式人工标注编辑':'AI候选标注编辑'" :aria-busy="snapshot.pending||mounting">
 <header class="editor-heading"><div><small>{{ formal ? '正式人工标注' : 'AI 候选人工编辑' }}</small><h2>{{ snapshot.filename||snapshot.imageId }}</h2><p>{{ snapshot.width }} × {{ snapshot.height }} · {{ snapshot.boxes.length }} 个框<span v-if="snapshot.revision!==undefined"> · {{ formal ? '标注版本' : '草稿版本' }} {{ snapshot.revision }}</span></p></div><el-button :disabled="snapshot.saving" @click="context.actions.cancel()">{{ formal ? '返回素材库' : '返回审核列表' }}</el-button></header>
 <div class="editor-tools" role="toolbar" aria-label="标注工具">
  <el-button v-for="[value,label] in [['select','选择 / 编辑'],['draw','画框'],['pan','平移']]" :key="value" :type="snapshot.view?.mode===value?'primary':'default'" :aria-pressed="snapshot.view?.mode===value" :disabled="locked" @click="context.actions.mode(value)">{{ label }}</el-button>
  <label>新框标签<select :value="snapshot.labelCode" :disabled="locked" aria-label="新框标签" @change="context.actions.label(changed($event))"><option v-if="!snapshot.labelCode" value="">请选择标签</option><option v-for="label in snapshot.labels" :key="label.code" :value="label.code">{{ label.display_name||label.name||label.code }} · {{ label.code }}</option></select></label>
  <el-button :disabled="locked" @click="context.actions.undo()">撤销</el-button><el-button :disabled="locked" @click="context.actions.redo()">重做</el-button>
  <el-button :disabled="locked" @click="context.actions.visibility()">{{ snapshot.view?.visible===false?'显示框':'隐藏框' }}</el-button>
  <label>显示类别<select :value="snapshot.filterCode||''" :disabled="locked" aria-label="显示类别" @change="context.actions.filter(changed($event))"><option value="">全部类别</option><option v-for="label in snapshot.labels" :key="label.code" :value="label.code">{{ label.display_name||label.code }}</option></select></label>
  <el-button :disabled="locked" aria-label="缩小" @click="context.actions.zoom(-0.1)">−</el-button><span class="editor-scale">{{ Math.round((snapshot.view?.scale??1)*100) }}%</span><el-button :disabled="locked" aria-label="放大" @click="context.actions.zoom(0.1)">＋</el-button><el-button :disabled="locked" @click="context.actions.fit()">适应窗口</el-button><el-button :disabled="locked" @click="context.actions.resetZoom()">100%</el-button>
 </div>
 <p v-if="snapshot.conflict" class="editor-notice" role="status">本图存在跨标签冲突，请核对框和类别；保存与入库由原审核规则校验。</p>
 <div class="editor-main"><div class="editor-canvas"><div ref="viewport" class="editor-viewport"><div ref="world" class="editor-world"><img ref="image" :key="snapshot.imageId+snapshot.url" :src="snapshot.url" :alt="snapshot.filename||'原图'" draggable="false" @load="mount" @error="imageFailed"></div></div><div v-if="!ready" class="editor-overlay" role="status"><p>{{ mountError||'正在读取原图与本地标注组件…' }}</p><el-button v-if="mountError" @click="retry">重试组件</el-button><el-button v-if="mountError" :disabled="snapshot.saving" @click="context.actions.reload()">{{ native ? '重新载入' : '原工作台重新载入' }}</el-button></div></div>
 <aside class="editor-objects" :aria-label="formal?'正式标注对象列表':'候选对象列表'"><h3>{{ formal ? '标注对象' : '候选对象' }} · {{ snapshot.boxes.length }}</h3><p v-if="!snapshot.boxes.length">当前没有标注框，可选择标签后画框。</p><article v-for="(box,index) in snapshot.boxes" :key="box.id" :class="{active:snapshot.activeBox===index}"><el-button :disabled="locked" :aria-label="`选择第${index+1}个框`" @click="context.actions.select(index)">#{{ index+1 }}</el-button><label><span class="sr-only">第{{ index+1 }}个框的类别</span><select :value="box.label" :disabled="locked" @change="context.actions.reclass(index,changed($event))"><option v-if="!snapshot.labels.some(label=>label.code===box.label)" :value="box.label">{{ box.label }}（待纠正）</option><option v-for="label in snapshot.labels" :key="label.code" :value="label.code">{{ label.display_name||label.code }} · {{ label.code }}</option></select></label><el-button :disabled="locked" type="danger" plain :aria-label="`删除第${index+1}个框`" @click="context.actions.remove(index)">删除</el-button></article></aside></div>
 <footer class="editor-footer"><slot name="footer" :ready="ready"><div role="status"><strong>{{ snapshot.dirty?'候选修改未保存':'候选草稿' }}</strong><span>{{ snapshot.error||snapshot.status||'保存候选草稿后仍需确认审核' }}</span></div><div class="editor-footer-actions"><el-button :disabled="snapshot.reloadDisabled ?? (snapshot.saving||(snapshot.pending&&!snapshot.editingDisabled))" @click="context.actions.reload()">重新载入草稿</el-button><el-button :disabled="snapshot.saving" @click="context.actions.cancel()">取消 / 返回</el-button><el-button type="primary" :disabled="!ready || snapshot.saving || snapshot.saveDisabled || (snapshot.pending && !snapshot.retryPending)" :loading="snapshot.saving" @click="context.actions.save()">{{ snapshot.retryPending ? '核验原保存请求' : '保存候选修改' }}</el-button></div></slot></footer>
</section></template>
<style scoped>
.vue-annotation-editor{display:flex;flex-direction:column;min-height:0;height:100%;background:var(--el-bg-color,#fff);color:var(--el-text-color-primary,#303133);overflow:hidden}.editor-heading,.editor-tools,.editor-footer{display:flex;align-items:center;gap:10px;padding:12px 16px;border-bottom:1px solid var(--el-border-color-lighter,#ebeef5)}.editor-heading,.editor-footer{justify-content:space-between}.editor-heading h2{font-size:18px;margin:3px 0;overflow-wrap:anywhere}.editor-heading p,.editor-heading small{margin:0;color:var(--el-text-color-secondary,#909399)}.editor-tools{flex-wrap:wrap;flex-shrink:0}.editor-tools label{display:flex;align-items:center;gap:6px;font-size:13px}.vue-annotation-editor select{font:inherit;max-width:230px;min-height:32px;border:1px solid var(--el-border-color,#dcdfe6);border-radius:4px;padding:4px 8px;background:var(--el-fill-color-blank,#fff);color:inherit}.vue-annotation-editor button:focus-visible,.vue-annotation-editor select:focus-visible{outline:2px solid var(--el-color-primary,#409eff);outline-offset:2px}.editor-scale{font-variant-numeric:tabular-nums;min-width:40px;text-align:center}.editor-main{display:grid;grid-template-columns:minmax(0,1fr) minmax(235px,290px);flex:1;min-height:180px;overflow:hidden}.editor-canvas{position:relative;min-width:0;min-height:0;overflow:hidden;background:#e9edf1}.editor-viewport{width:100%;height:100%;position:relative;overflow:hidden;touch-action:none}.editor-world{position:absolute;left:0;top:0;transform-origin:0 0}.editor-world img{display:block;max-width:none;user-select:none}.editor-overlay{position:absolute;inset:0;display:flex;flex-wrap:wrap;align-content:center;align-items:center;justify-content:center;gap:10px;background:var(--el-mask-color,rgba(255,255,255,.9));padding:20px;text-align:center}.editor-overlay p{width:100%}.editor-objects{overflow:auto;padding:12px;border-left:1px solid var(--el-border-color-lighter,#ebeef5)}.editor-objects h3{font-size:14px;margin:0 0 12px}.editor-objects article{display:flex;gap:6px;align-items:center;padding:8px 4px;border-bottom:1px solid var(--el-border-color-lighter,#ebeef5)}.editor-objects article.active{background:var(--el-color-primary-light-9,#ecf5ff)}.editor-objects label{flex:1;min-width:0}.editor-objects select{width:100%;max-width:100%}.editor-objects :deep(.el-button){margin-left:0;padding:6px 9px}.editor-footer{flex-shrink:0;border-top:1px solid var(--el-border-color-lighter,#ebeef5);border-bottom:0;flex-wrap:wrap}.editor-footer>div:first-child{display:flex;flex-direction:column;gap:4px;min-width:0;overflow-wrap:anywhere}.editor-footer-actions{display:flex;gap:8px;flex-wrap:wrap}.editor-footer-actions :deep(.el-button){margin-left:0}.editor-notice{margin:0;padding:9px 16px;background:var(--el-color-warning-light-9,#fdf6ec);font-size:13px}.sr-only{position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap}
@media(max-width:900px){.editor-main{grid-template-columns:minmax(0,1fr) 225px}.editor-tools{gap:6px;padding:8px}.editor-tools :deep(.el-button){margin-left:0}.editor-heading{padding:10px}.editor-footer{padding:8px}}
@media(max-width:640px){.editor-main{grid-template-columns:minmax(0,1fr);grid-template-rows:minmax(180px,1fr) 150px}.editor-objects{border-left:0;border-top:1px solid var(--el-border-color-lighter,#ebeef5)}.editor-heading h2{font-size:15px}.editor-tools select{max-width:160px}}
</style>
